import {
  type ExecSyncOptionsWithBufferEncoding,
  execSync,
} from "child_process";
import { existsSync } from "fs";

const lockfiles = {
  pnpm: "pnpm-lock.yaml",
  npm: "package-lock.json",
};

export const npm = (cmd: string, opts?: ExecSyncOptionsWithBufferEncoding) => {
  if (existsSync(lockfiles.pnpm)) {
    return execSync(`pnpm ${cmd}`, opts);
  }

  if (existsSync(lockfiles.npm)) {
    return execSync(`npm ${cmd}`, opts);
  }

  throw new Error("Could not find a lockfile.");
};

export const npx = (cmd: string, opts?: ExecSyncOptionsWithBufferEncoding) => {
  return execSync(`npx ${cmd}`, opts);

  // throw new Error("Could not find a lockfile.");
};

import { detectExerciseType } from "./detectExerciseType";
import { findExerciseInCwd } from "./findAllExercises";
import { runFileBasedExercise } from "./runFileBasedExercise";
import { runPackageJsonExercise } from "./runPackageJsonExercise";

export const runExercise = async (exercise: string, runSolution: boolean) => {
  if (!exercise) {
    console.log("Please specify an exercise");
    process.exit(1);
  }

  const exerciseFile = await findExerciseInCwd(exercise, runSolution);

  await runExerciseFile(exerciseFile);
};

export const runExerciseFile = async (exercisePath: string) => {
  const exerciseType = await detectExerciseType(exercisePath);

  if (exerciseType === "not-runnable") {
    console.log(`This exercise doesn't need the CLI.`.bold);

    console.log(
      ` - ` +
        `You haven't done anything wrong!`.bold +
        ` Your setup is working correctly.`,
    );

    console.log(
      ` - ` +
        `But this exercise doesn't require the CLI to be run to complete it.`,
    );

    console.log(
      ` - Instead, ` +
        `follow the instructions in the video`.bold +
        ` to complete the exercise.`,
    );

    process.exit(0);
  }

  switch (exerciseType) {
    case "file":
      return await runFileBasedExercise(exercisePath);

    case "package-json-with-dev-script":
      return await runPackageJsonExercise(exercisePath);
  }
  exerciseType satisfies never;
};

import { execSync } from "child_process";
import "colors";
import { readFileSync, writeFileSync } from "fs";
import { stat } from "fs/promises";
import * as path from "path";
import { cleanVitestOutput } from "./cleanVitestOutput";
import { isDir } from "./detectExerciseType";
import { findAllExercises } from "./findAllExercises";
import { npx } from "./install";

type Snapshot = {
  title: string;
  content: string;
};

const getTSSnapshotFromFolder = (folder: string): string => {
  let result: string;
  try {
    result = npx(`tsc`, {
      cwd: folder,
    }).toString();
  } catch (error: any) {
    result = error.output.toString();
  }
  return result;
};

const getTSSnapshotFromFolderExercises = async (
  rootFolder: string,
): Promise<string> => {
  const srcPath = path.resolve(rootFolder, "./src");
  const exercises = await findAllExercises(srcPath, {
    allowedTypes: ["problem", "explainer", "solution"],
  });

  const exercisesWhichAreFolders = [];

  for (const filePath of exercises) {
    if (await isDir(filePath)) {
      try {
        const tsconfigPath = path.resolve(filePath, "tsconfig.json");

        if (await stat(tsconfigPath)) {
          exercisesWhichAreFolders.push(filePath);
        }
      } catch (e) {}
    }
  }

  let snapshots: Snapshot[] = [];

  for (const exerciseFolder of exercisesWhichAreFolders) {
    const tsSnapshot = getTSSnapshotFromFolder(exerciseFolder);

    snapshots.push({
      title: exerciseFolder,
      content: tsSnapshot,
    });
  }

  return snapshots.reduce((acc, snapshot) => {
    return [
      acc,
      "",
      `# [](${path.relative(
        rootFolder,
        path.join(snapshot.title, "tsconfig.json"),
      )})`,
      "",
      "```txt",
      snapshot.content,
      "```",
    ].join("\n");
  }, "");
};

const getTSSnapshot = async (rootFolder: string): Promise<string> => {
  const rootTSSnapshot = getTSSnapshotFromFolder(rootFolder);

  const tsSnapshotFromFolderExercises = await getTSSnapshotFromFolderExercises(
    rootFolder,
  );

  return [
    `# Root TSConfig Snapshot`,
    "",
    "```txt",
    rootTSSnapshot,
    "```",
    "",
    tsSnapshotFromFolderExercises,
  ].join("\n");
};

const getVitestSnapshot = (rootFolder: string): string => {
  let result: string;

  try {
    result = npx(`vitest run --reporter=json`, {
      cwd: rootFolder,
      stdio: "pipe",
    }).toString();
  } catch (error: any) {
    result = error.output.toString();
  }

  const vitestOutput = cleanVitestOutput(result, {
    rootFolder,
  });

  return [
    `# Vitest Snapshot`,
    "",
    "```json",
    JSON.stringify(vitestOutput, null, 2),
    "```",
  ].join("\n");
};

const getSnapshot = async () => {
  const tsSnapshot = await getTSSnapshot(process.cwd());

  const vitestSnapshot = getVitestSnapshot(process.cwd());

  const fullSnapshot = tsSnapshot + "\n\n" + vitestSnapshot;

  return fullSnapshot;
};

export const takeSnapshot = async (outPath: string) => {
  const fullSnapshot = await getSnapshot();
  writeFileSync(outPath, fullSnapshot);
};

export const compareSnapshotAgainstExisting = async (outPath: string) => {
  const newSnapshot = await getSnapshot();
  const existingSnapshot = readFileSync(outPath, "utf8");

  if (newSnapshot !== existingSnapshot) {
    execSync(`git add ${outPath}`, { stdio: "inherit" });

    writeFileSync(outPath, newSnapshot);

    console.log("Snapshots differ. Showing diff:");

    execSync(`git --no-pager diff --unified=0 ${outPath}`, { stdio: "inherit" });
    process.exit(1);
  }
};

import * as fg from "fast-glob";
import { readdir } from "fs/promises";
import path from "path";
import { isDir } from "./detectExerciseType";

const searchToGlob = (search: {
  num?: string;
  allowedTypes?: ("explainer" | "solution" | "problem")[];
}) => {
  return `**/${search?.num ?? ""}*.{${search?.allowedTypes?.join(",") ?? ""}}*`;
};

export const findExerciseInCwd = async (
  exercise: string,
  runSolution: boolean,
): Promise<string> => {
  const srcPath = path.resolve(process.cwd(), "./src");

  const exerciseFile = await findExercise(srcPath, {
    num: exercise,
    allowedTypes: ["explainer", runSolution ? "solution" : "problem"],
  });

  if (!exerciseFile) {
    console.log(`Exercise ${exercise} not found`);
    process.exit(1);
  }

  return exerciseFile;
};

export const findAllSections = async (
  srcPath: string,
): Promise<{
  sections: {
    name: string;
    files: string[];
  }[];
  isASectionRepo: boolean;
}> => {
  const dirContents = await readdir(srcPath);

  const allSections: {
    name: string;
    files: string[];
  }[] = [];

  const exercises = await findAllExercises(srcPath, {
    allowedTypes: ["explainer", "problem", "solution"],
  });

  for (const dir of dirContents) {
    if (await isDir(path.join(srcPath, dir))) {
      const pathToSection = path.join(srcPath, dir);
      allSections.push({
        name: dir,
        files: exercises.filter((exercise) => {
          return exercise.startsWith(pathToSection);
        }),
      });
    }
  }

  return {
    sections: allSections.sort((a, b) => a.name.localeCompare(b.name)),
    // If there is anything else in the src directory that is not a dir,
    // then this is not a 'section' repo
    isASectionRepo: allSections.length === dirContents.length,
  };
};

export const findAllExercises = async (
  srcPath: string,
  search: {
    num?: string;
    allowedTypes: ("explainer" | "solution" | "problem")[];
  },
): Promise<string[]> => {
  const glob = searchToGlob(search || {});

  const allExercises = await fg.default(
    path.join(srcPath, "**", glob).replace(/\\/g, "/"),
    {
      onlyFiles: false,
    },
  );

  return allExercises.sort((a, b) => a.localeCompare(b));
};

export const findExercise = async (
  srcPath: string,
  search: {
    num?: string;
    allowedTypes?: ("explainer" | "solution" | "problem")[];
  },
): Promise<string | undefined> => {
  const glob = searchToGlob(search);

  const allExercises = await fg.default(
    path.join(srcPath, "**", glob).replace(/\\/g, "/"),
    {
      onlyFiles: false,
    },
  );

  return allExercises[0];
};

import fs from "fs/promises";
import path from "path";

export type ExerciseType =
  | "file"
  | "package-json-with-dev-script"
  | "not-runnable";

const endsWithTsOrTsx = (filepath: string) =>
  filepath.endsWith(".ts") || filepath.endsWith(".tsx");

export const isDir = async (filepath: string) => {
  const stat = await fs.stat(filepath);

  return stat.isDirectory();
};

export const detectExerciseType = async (
  filepath: string,
): Promise<ExerciseType> => {
  if (endsWithTsOrTsx(filepath)) {
    return "file";
  }

  if (await isDir(filepath)) {
    const packageJsonPath = path.resolve(filepath, "package.json");

    try {
      const packageJson = await fs.readFile(packageJsonPath, "utf-8");

      const parsed = JSON.parse(packageJson);

      if (parsed?.scripts?.dev) {
        return "package-json-with-dev-script";
      }
    } catch (e) {}
  }

  return "not-runnable";
};

import { execSync } from "child_process";

export const runPackageJsonExercise = async (exerciseFile: string) => {
  // Install the packages with pnpm
  execSync("pnpm install", {
    cwd: exerciseFile,
    stdio: "inherit",
  });

  // Run the dev script of the package.json

  execSync("pnpm run dev", {
    cwd: exerciseFile,
    stdio: "inherit",
  });
};

import { execSync } from "child_process";
import * as chokidar from "chokidar";
import * as fs from "fs/promises";
import { parse as jsonCParse } from "jsonc-parser";
import * as path from "path";

/**
 * Runs exercises that are based on a single file,
 * like 01-whatever.problem.ts
 */
export const runFileBasedExercise = async (exerciseFile: string) => {
  const tempTsconfigPath = path.resolve(process.cwd(), "./tsconfig.temp.json");

  const tsconfigPath = path.resolve(process.cwd(), "./tsconfig.json");
  const tsconfig = jsonCParse(await fs.readFile(tsconfigPath, "utf8"));

  chokidar.watch(exerciseFile).on("all", async () => {
    const fileContents = await fs.readFile(exerciseFile, "utf8");

    const containsVitest =
      fileContents.includes(`from "vitest"`) ||
      fileContents.includes(`from 'vitest'`);
    try {
      console.clear();
      if (containsVitest) {
        console.log("Running tests...");
        execSync(`vitest run "${exerciseFile}" --passWithNoTests`, {
          stdio: "inherit",
        });
      }
      console.log("Checking types...");

      // Write a temp tsconfig.json
      const tsconfigWithIncludes = {
        ...tsconfig,
        include: [exerciseFile],
      };

      await fs.writeFile(
        tempTsconfigPath,
        JSON.stringify(tsconfigWithIncludes, null, 2),
      );

      execSync(`tsc --project "${tempTsconfigPath}"`, {
        stdio: "inherit",
      });
      console.log("Typecheck complete. You finished the exercise!");
    } catch (e) {
      console.log("Failed. Try again!");
    } finally {
      try {
        await fs.rm(tempTsconfigPath);
      } catch (e) {}
    }
  });
};

