import * as fs from "fs/promises";
import * as path from "path";
import { findAllExercises } from "./findAllExercises";

const getPackageJsonScript = (
  exercise: string,
  type: "exercise" | "solution",
): string => {
  return [`tt-cli run ${exercise} ${type === "solution" ? "--solution" : ""}`]
    .join(" && ")
    .trim();
};

/**
 * Adds a bunch of scripts, like e-01, e-02 to package.json
 * so that StackBlitz can run them programmatically via URL
 * commands
 */
export const prepareStackblitz = async () => {
  const packageJsonPath = path.resolve(process.cwd(), "package.json");
  const packageJson = JSON.parse(await fs.readFile(packageJsonPath, "utf8"));

  const srcPath = path.resolve(process.cwd(), "./src");
  const exerciseFiles = await findAllExercises(srcPath, {
    allowedTypes: ["problem", "explainer"],
  });
  const exerciseNumbers: string[] = exerciseFiles.map(
    (exercise) => path.parse(exercise).base.split("-")[0]!,
  );

  const newPackageJson = Object.assign({}, packageJson);

  newPackageJson.scripts = {
    ...packageJson.scripts,
  };

  const scriptsWeControl = Object.keys(packageJson.scripts).filter((script) => {
    return script.startsWith("e-") || script.startsWith("s-");
  });

  scriptsWeControl.forEach((script) => {
    delete newPackageJson.scripts[script];
  });

  exerciseNumbers.forEach((exerciseNumber) => {
    newPackageJson.scripts[`e-${exerciseNumber}`] = getPackageJsonScript(
      exerciseNumber,
      "exercise",
    );
    newPackageJson.scripts[`s-${exerciseNumber}`] = getPackageJsonScript(
      exerciseNumber,
      "solution",
    );
  });

  await fs.writeFile(packageJsonPath, JSON.stringify(newPackageJson, null, 2));
};

#!/usr/bin/env node

import { totalTypeScriptCLI } from "./command";

totalTypeScriptCLI.parse();

import prompts from "prompts";
import path from "path";
import { findAllExercises } from "./findAllExercises";
import { runExerciseFile } from "./runExercise";

export const runPrompts = async () => {
  const srcPath = path.resolve(process.cwd(), "./src");

  const exercises = await findAllExercises(srcPath, {
    allowedTypes: ["explainer", "problem", "solution"],
  });

  const { exercisePath }: { exercisePath: string } = await prompts({
    type: "autocomplete",
    message: "Select an exercise file to run (type to autocomplete)",
    name: "exercisePath",
    async suggest(input: string, choices) {
      return choices.filter((choice) => {
        return choice.title.toLowerCase().includes(input.toLowerCase());
      });
    },
    choices: exercises.map((exercise) => {
      const exerciseName = path.basename(exercise);

      return {
        title: exerciseName,
        value: exercise,
      };
    }),
  });

  await runExerciseFile(exercisePath);
};

import { Command } from "commander";
import { runExercise } from "./runExercise";
import { prepareStackblitz } from "./prepareStackblitz";
import {
  compareSnapshotAgainstExisting,
  takeSnapshot,
} from "./snapshotExercises";
import { runPrompts } from "./runPrompts";
import packageJson from "../package.json" with { type: "json" };
import { createSectionRepos } from "./create-section-repos";

export const totalTypeScriptCLI = new Command();

totalTypeScriptCLI.version(packageJson.version);

totalTypeScriptCLI
  .command("run [exercise]")
  .alias("exercise [exercise]")
  .description("Runs an exercise on watch mode")
  .option("-s, --solution", "Run the solution")
  .action(
    (
      exercise: string,
      options: {
